function generatePrompt() {
    const cameraParts = [];
    const humanParts = [];

    // === CAMERA BEHAVIOR ===
    if (state.sections.camera) {
        // Device description
        const deviceDescriptions = {
            'smartphone_handheld': 'handheld smartphone camera',
            'smartphone_selfie': 'smartphone selfie cam front-facing',
            'action_cam': 'action camera GoPro-style wide angle',
            'dslr_shoulder': 'DSLR camera shoulder-mounted documentary style',
            'dslr_handheld': 'DSLR handheld cinema camera',
            'dashcam': 'fixed dashcam perspective',
            'security': 'static security camera CCTV angle',
            'webcam': 'laptop webcam fixed position'
        };

        cameraParts.push(`Shot on ${deviceDescriptions[state.camera.device]}.`);

        // Camera micro-movements
        const cameraMovements = [];

        if (state.camera.handDrift > 0) {
            cameraMovements.push(`subtle hand drift of ${state.camera.handDrift}mm amplitude at ${state.camera.driftFreq} movements per second`);
        }

        if (state.camera.microShake > 0) {
            const shakeIntensity = ['', 'barely perceptible', 'slight', 'noticeable', 'pronounced', 'heavy'][state.camera.microShake];
            cameraMovements.push(`${shakeIntensity} micro-shake from human hand instability`);
        }

        if (state.camera.afBreathing > 0) {
            const afIntensity = ['', 'minimal', 'subtle', 'natural', 'visible', 'prominent'][state.camera.afBreathing];
            cameraMovements.push(`${afIntensity} autofocus breathing and hunting`);
        }

        if (state.camera.aeShift > 0) {
            cameraMovements.push(`auto-exposure micro-adjustments of +/-${state.camera.aeShift} stops`);
        }

        if (cameraMovements.length > 0) {
            cameraParts.push(`Camera behavior: ${cameraMovements.join(', ')}.`);
        }

        // Operator behaviors
        const operatorBehaviors = [];
        if (state.camera.gazeBreaks) operatorBehaviors.push('brief gaze breaks lasting 0.2-0.4 seconds');
        if (state.camera.reframing) operatorBehaviors.push('subtle reframing adjustments');
        if (state.camera.zoomHunting) operatorBehaviors.push('occasional zoom hunting');
        if (state.camera.whipPan) operatorBehaviors.push('spontaneous whip pans');
        if (state.camera.freeRoam) operatorBehaviors.push('free-roaming camera movement exploring subject from multiple angles, pushing in for details then pulling back, circling loosely, finding new perspectives organically');

        // Orbit movement
        if (state.camera.orbit) {
            const orbitSpeedDesc = ['', 'slow', 'medium', 'fast', 'rapid'][state.camera.orbitSpeed];
            const orbitDirDesc = {
                'clockwise': 'clockwise',
                'counterclockwise': 'counter-clockwise',
                'alternating': 'alternating directions'
            }[state.camera.orbitDirection];
            operatorBehaviors.push(`smooth orbital camera movement circling around subject at ${orbitSpeedDesc} pace, ${orbitDirDesc}, maintaining consistent distance while tracking subject`);
        }

        // Stop motion frame vibration
        if (state.camera.stopMotionVib > 0) {
            const vibDesc = ['', 'barely perceptible micro-vibration between frames like stop-motion camera bump', 'subtle frame-to-frame position jitter characteristic of stop-motion animation', 'visible stop-motion camera vibration with slight position shifts each frame', 'pronounced stop-motion tremor with noticeable inter-frame camera displacement'][state.camera.stopMotionVib];
            cameraParts.push(`Stop-motion effect: ${vibDesc}.`);
        }

        if (operatorBehaviors.length > 0) {
            cameraParts.push(`Operator behavior: ${operatorBehaviors.join(', ')}.`);
        }
    }

    // === HUMAN MICRO-MOTION ===
    if (state.sections.human) {
        // Human activity level
        const activityDescriptions = {
            'still': 'Subject seated or still',
            'casual': 'Subject in casual standing position',
            'active': 'Subject actively moving',
            'nervous': 'Subject displaying nervous energy',
            'exhausted': 'Subject with low energy exhausted demeanor',
            'puppet_henson': 'Subject moves like a Jim Henson foam puppet, gentle bouncy sway originating from below, head bobs and tilts expressively during speech, arms swing loosely with slight delay, exaggerated mouth movements, soft floaty quality to all motion, occasional looking-around head movements, body gently rocks side to side, movements have warmth and personality of classic Muppet performance',
            'puppet_stopmotion': 'Subject moves in stop-motion animation style at 12 frames per second, distinct stuttery motion with visible holds between poses, micro-jitter from animator touch, imperfect spacing between keyframes, slight position drift between frames, characteristic jerky puppet quality, movements have deliberate start-stop rhythm, subtle tremor artifacts from physical manipulation'
        };
        humanParts.push(activityDescriptions[state.human.activityLevel] + '.');

        // Body micro-motion
        const bodyMotion = [];

        if (state.human.breathSway > 0) {
            const swayIntensity = ['', 'minimal', 'subtle', 'natural', 'visible', 'pronounced'][state.human.breathSway];
            bodyMotion.push(`${swayIntensity} breathing sway in torso and shoulders`);
        }

        if (state.human.weightShift > 0) {
            const shiftFreq = ['', 'rare', 'occasional', 'periodic', 'frequent', 'constant'][state.human.weightShift];
            bodyMotion.push(`${shiftFreq} weight shifts between feet`);
        }

        if (state.human.gripAdjust) bodyMotion.push('micro grip adjustments');
        if (state.human.postureShift) bodyMotion.push('subtle posture corrections');
        if (state.human.fidget) bodyMotion.push('idle fidgeting');
        if (state.human.handGesture) bodyMotion.push('natural hand gestures while speaking');

        if (bodyMotion.length > 0) {
            humanParts.push(`Body micro-motion: ${bodyMotion.join(', ')}.`);
        }

        // Facial micro-expressions
        const facialMotion = [];

        if (state.human.blinkRate > 0) {
            const blinkDesc = ['', '5-10 blinks per minute sparse', '10-15 blinks per minute slow', '15-20 blinks per minute natural rate', '20-25 blinks per minute frequent', '25+ blinks per minute nervous rapid'][state.human.blinkRate];
            facialMotion.push(blinkDesc);
        }

        if (state.human.microExpressions) facialMotion.push('subtle micro-expressions');
        if (state.human.eyeDart) facialMotion.push('natural eye saccades and micro-movements');
        if (state.human.lipMovement) facialMotion.push('lip micro-movements');
        if (state.human.swallow) facialMotion.push('occasional swallow reflex');

        if (facialMotion.length > 0) {
            humanParts.push(`Facial micro-motion: ${facialMotion.join(', ')}.`);
        }

        // Speech patterns
        const speechPatterns = [];
        if (state.human.naturalPause) speechPatterns.push('natural pauses in speech');
        if (state.human.breathBetween) speechPatterns.push('audible breaths between sentences');
        if (state.human.umFiller) speechPatterns.push('occasional filler words um uh');
        if (state.human.headNod) speechPatterns.push('head nods for emphasis while speaking');

        if (speechPatterns.length > 0) {
            humanParts.push(`Speech patterns: ${speechPatterns.join(', ')}.`);
        }
    }

    // Anti-glitch rules (always included if active)
    const antiGlitchRules = [];
    if (state.antiGlitch.noMorphing) antiGlitchRules.push('no face morphing or distortion');
    if (state.antiGlitch.consistentFingers) antiGlitchRules.push('consistent finger count exactly five fingers per hand');
    if (state.antiGlitch.noFlicker) antiGlitchRules.push('no texture flickering or swimming artifacts');
    if (state.antiGlitch.stableClothing) antiGlitchRules.push('stable consistent clothing and accessories');
    if (state.antiGlitch.naturalMotion) antiGlitchRules.push('physically plausible motion only');
    if (state.antiGlitch.consistentLighting) antiGlitchRules.push('consistent lighting direction throughout');
    if (state.antiGlitch.noTextWarp) antiGlitchRules.push('no warping or morphing text or logos');
    if (state.antiGlitch.stableBackground) antiGlitchRules.push('stable non-morphing background elements');
    if (state.antiGlitch.naturalHair) antiGlitchRules.push('natural hair movement physics');
    if (state.antiGlitch.eyeContact) antiGlitchRules.push('maintain consistent eye contact direction');

    // Final assembly with separation
    const allParts = [];

    if (cameraParts.length > 0) {
        allParts.push('[CAMERA]\n' + cameraParts.join(' '));
    }

    if (humanParts.length > 0) {
        allParts.push('[SUBJECT]\n' + humanParts.join(' '));
    }

    if (antiGlitchRules.length > 0) {
        allParts.push('[CONSTRAINTS]\n' + antiGlitchRules.join('. ') + '.');
    }

    const finalPrompt = allParts.join('\n\n');
    document.getElementById('outputPrompt').value = finalPrompt;

    // Update stats
    const realismScore = calculateRealismScore();
    document.getElementById('realismScore').textContent = realismScore + '%';
    document.getElementById('antiGlitchCount').textContent = antiGlitchRules.length + ' active';
    document.getElementById('tokenCount').textContent = '~' + Math.ceil(finalPrompt.split(' ').length * 1.3);
}

