function calculateRealismScore() {
    let score = 50; // Base score

    // Camera factors
    if (state.camera.handDrift > 0) score += Math.min(state.camera.handDrift * 3, 10);
    if (state.camera.microShake > 0) score += state.camera.microShake * 2;
    if (state.camera.afBreathing > 0) score += state.camera.afBreathing * 2;
    if (state.camera.gazeBreaks) score += 5;
    if (state.camera.reframing) score += 3;

    // Human factors
    if (state.human.breathSway > 0) score += state.human.breathSway * 2;
    if (state.human.blinkRate > 0) score += 5;
    if (state.human.microExpressions) score += 5;
    if (state.human.eyeDart) score += 5;
    if (state.human.gripAdjust) score += 3;

    // Anti-glitch penalty (too few = risky)
    const activeRules = Object.values(state.antiGlitch).filter(v => v).length;
    if (activeRules < 4) score -= 10;

    return Math.min(Math.max(score, 0), 100);
}
